css:
.eileader-sim-container {
    padding: 28px;
    background: #151b26;
    min-height: 100vh;
    font-family: -apple-system, 'Segoe UI', 'Inter', sans-serif;
    color: #e2e8f0;
}
.eileader-sim-header {
    background: linear-gradient(135deg, #1a2a3a 0%, #0d2137 60%, #1a2744 100%);
    border-radius: 16px;
    padding: 36px 32px;
    text-align: center;
    margin-bottom: 24px;
    border: 1px solid #2a3a50;
    position: relative;
    overflow: hidden;
}
.eileader-sim-header::before {
    content: '';
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
    height: 3px;
    background: linear-gradient(90deg, #e8a838, #38b2ac, #e8a838);
}
.eileader-sim-header-icon {
    font-size: 2.4rem;
    margin-bottom: 8px;
}
.eileader-sim-header h1 {
    color: #f0e6d3;
    font-size: 1.6rem;
    font-weight: 700;
    margin: 0 0 6px 0;
    letter-spacing: 0.02em;
}
.eileader-sim-subtitle {
    color: #8dabc4;
    font-size: 0.95rem;
    margin: 0;
    font-weight: 400;
}
.eileader-sim-period-counter {
    text-align: center;
    font-size: 1rem;
    color: #8896b3;
    margin-bottom: 24px;
    font-weight: 500;
}
.eileader-sim-period-counter span:nth-child(2),
.eileader-sim-period-counter span:nth-child(4) {
    color: #e8a838;
    font-weight: 700;
    font-size: 1.15rem;
}
.eileader-sim-briefing {
    background: #1e2536;
    border: 1px solid #2a3a50;
    border-left: 4px solid #e8a838;
    border-radius: 12px;
    padding: 24px 28px;
    margin-bottom: 28px;
    position: relative;
}
.eileader-sim-briefing-badge {
    display: inline-block;
    background: rgba(232,168,56,0.15);
    color: #e8a838;
    font-size: 0.72rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    padding: 4px 12px;
    border-radius: 20px;
    margin-bottom: 12px;
}
.eileader-sim-briefing-title {
    color: #f0e6d3;
    font-size: 1.15rem;
    font-weight: 600;
    margin: 0 0 10px 0;
}
.eileader-sim-briefing-text {
    color: #a8b8cc;
    font-size: 0.92rem;
    line-height: 1.65;
    margin: 0;
}
.eileader-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
    gap: 14px;
    margin-bottom: 28px;
}
.eileader-sim-kpi-card {
    background: #1e2536;
    border: 1px solid #2a3348;
    border-radius: 12px;
    padding: 20px 16px 16px;
    text-align: center;
    transition: transform 0.2s ease, border-color 0.2s ease;
    position: relative;
}
.eileader-sim-kpi-card:hover {
    transform: translateY(-3px);
    border-color: #3a4a60;
}
.eileader-sim-kpi-icon {
    font-size: 1.4rem;
    margin-bottom: 6px;
}
.eileader-sim-kpi-label {
    color: #7c8db5;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin-bottom: 8px;
    font-weight: 600;
}
.eileader-sim-kpi-value {
    font-size: 2rem;
    font-weight: 700;
    margin-bottom: 10px;
}
.eileader-kpi-morale .eileader-sim-kpi-value { color: #38b2ac; }
.eileader-kpi-reputation .eileader-sim-kpi-value { color: #6b8cce; }
.eileader-kpi-patients .eileader-sim-kpi-value { color: #e8594e; }
.eileader-kpi-wellbeing .eileader-sim-kpi-value { color: #e8a838; }
.eileader-kpi-retention .eileader-sim-kpi-value { color: #a78bfa; }
.eileader-sim-kpi-bar {
    width: 100%;
    height: 5px;
    background: #2a3348;
    border-radius: 3px;
    overflow: hidden;
}
.eileader-sim-kpi-bar-fill {
    height: 100%;
    border-radius: 3px;
    transition: width 0.6s ease;
}
.eileader-kpi-morale .eileader-sim-kpi-bar-fill { background: #38b2ac; }
.eileader-kpi-reputation .eileader-sim-kpi-bar-fill { background: #6b8cce; }
.eileader-kpi-patients .eileader-sim-kpi-bar-fill { background: #e8594e; }
.eileader-kpi-wellbeing .eileader-sim-kpi-bar-fill { background: #e8a838; }
.eileader-kpi-retention .eileader-sim-kpi-bar-fill { background: #a78bfa; }
.eileader-sim-controls {
    background: #1e2536;
    border: 1px solid #2a3348;
    border-radius: 12px;
    padding: 28px;
    margin-bottom: 28px;
}
.eileader-sim-controls h3 {
    color: #f0e6d3;
    font-size: 1.1rem;
    font-weight: 600;
    margin: 0 0 20px 0;
    padding-bottom: 12px;
    border-bottom: 1px solid #2a3348;
}
.eileader-sim-slider-group {
    margin-bottom: 22px;
}
.eileader-sim-slider-group label {
    display: block;
    color: #c5d0e0;
    font-size: 0.88rem;
    font-weight: 500;
    margin-bottom: 8px;
}
.eileader-sim-slider-row {
    display: flex;
    align-items: center;
    gap: 14px;
}
.eileader-sim-range {
    flex: 1;
    -webkit-appearance: none;
    appearance: none;
    height: 6px;
    background: #2a3a50;
    border-radius: 3px;
    outline: none;
}
.eileader-sim-range::-webkit-slider-thumb {
    -webkit-appearance: none;
    appearance: none;
    width: 22px;
    height: 22px;
    border-radius: 50%;
    background: #e8a838;
    cursor: pointer;
    border: 3px solid #151b26;
    box-shadow: 0 0 8px rgba(232,168,56,0.3);
    transition: box-shadow 0.2s ease;
}
.eileader-sim-range::-webkit-slider-thumb:hover {
    box-shadow: 0 0 14px rgba(232,168,56,0.5);
}
.eileader-sim-range::-moz-range-thumb {
    width: 22px;
    height: 22px;
    border-radius: 50%;
    background: #e8a838;
    cursor: pointer;
    border: 3px solid #151b26;
    box-shadow: 0 0 8px rgba(232,168,56,0.3);
}
.eileader-sim-range-value {
    min-width: 36px;
    text-align: center;
    font-size: 1.1rem;
    font-weight: 700;
    color: #e8a838;
    background: #2a3348;
    border-radius: 8px;
    padding: 4px 8px;
}
.eileader-sim-slider-hints {
    display: flex;
    justify-content: space-between;
    font-size: 0.7rem;
    color: #5e6e8a;
    margin-top: 4px;
    text-transform: uppercase;
    letter-spacing: 0.06em;
}
.eileader-sim-submit {
    display: block;
    width: 100%;
    padding: 14px;
    font-size: 1rem;
    font-weight: 600;
    border: none;
    border-radius: 10px;
    background: linear-gradient(135deg, #e8a838, #d4922e);
    color: #151b26;
    cursor: pointer;
    transition: transform 0.15s ease, box-shadow 0.2s ease;
    margin-top: 8px;
    letter-spacing: 0.02em;
}
.eileader-sim-submit:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 20px rgba(232,168,56,0.3);
    background: linear-gradient(135deg, #f0b440, #e8a838);
    color: #151b26;
}
.eileader-sim-undo {
    display: block;
    margin: 12px auto 0;
    color: #7c8db5;
    border-color: #3a4a60;
    font-size: 0.82rem;
}
.eileader-sim-undo:hover {
    color: #c5d0e0;
    border-color: #5a6a80;
    background: rgba(255,255,255,0.04);
}
.eileader-sim-feedback {
    background: #1a2a3a;
    border: 1px solid #2a3a50;
    border-left: 4px solid #38b2ac;
    border-radius: 12px;
    padding: 20px 24px;
    margin-bottom: 28px;
}
.eileader-sim-feedback h4 {
    color: #38b2ac;
    font-size: 0.9rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    margin: 0 0 10px 0;
}
.eileader-sim-feedback p {
    color: #a8b8cc;
    font-size: 0.9rem;
    line-height: 1.6;
    margin: 0;
}
.eileader-sim-chart-area {
    background: #1e2536;
    border: 1px solid #2a3348;
    border-radius: 12px;
    padding: 24px;
    margin-bottom: 28px;
    height: 320px;
    position: relative;
}
.eileader-sim-history {
    background: #1e2536;
    border: 1px solid #2a3348;
    border-radius: 12px;
    padding: 20px;
    overflow-x: auto;
}
.eileader-sim-container .table {
    color: #c5d0e0;
    margin: 0;
}
.eileader-sim-container .table thead th {
    border-color: #2a3348;
    color: #7c8db5;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    font-weight: 600;
    background: #1a2030;
}
.eileader-sim-container .table td {
    border-color: #2a3348;
    font-size: 0.88rem;
    vertical-align: middle;
}
.eileader-sim-container .table-striped tbody tr:nth-of-type(odd) {
    background-color: rgba(255,255,255,0.02);
}
@media (max-width: 768px) {
    .eileader-sim-container { padding: 16px; }
    .eileader-sim-header { padding: 24px 18px; }
    .eileader-sim-header h1 { font-size: 1.25rem; }
    .eileader-sim-kpi-grid { grid-template-columns: repeat(2, 1fr); }
    .eileader-sim-kpi-value { font-size: 1.5rem; }
    .eileader-sim-controls { padding: 18px; }
    .eileader-sim-chart-area { height: 260px; padding: 16px; }
    .eileader-sim-briefing { padding: 18px 20px; }
}
@media (max-width: 480px) {
    .eileader-sim-kpi-grid { grid-template-columns: 1fr 1fr; gap: 10px; }
    .eileader-sim-kpi-card { padding: 14px 10px 12px; }
}

